// FS26 situational judgement practice bank (data only; no default export, so the ext loader skips it as a builder).
// 48 items, three per FS25 core skill, written for a nuclear plant in English and Arabic. Each response carries the expert effectiveness
// (0 counterproductive, 1 weak, 2 acceptable, 3 the expert's best response) and a why; each item an expert rationale in both languages.
// Synthetic scenarios: no real people, no plant-security arrangements, no exam content. Pattern: IAEA-TECDOC-1917 situational judgement
// items for safety behaviours (conservative decisions, questioning attitude, raising concerns, teamwork under pressure).
const O = (en, ar, eff, note_en, note_ar) => ({ en, ar, eff, note_en, note_ar });
const I = (core_skill_id, theme, stem_en, stem_ar, options, rationale_en, rationale_ar) => ({ core_skill_id, theme, stem_en, stem_ar, options, rationale_en, rationale_ar });

export const ITEMS = [
  // ───────────── TC-1 Questioning attitude
  I('cs-questioning', 'questioning',
    'During a walkdown you see a tag on a valve that names a different work order from the one in your package. The control room says the tag is probably left over from last week. What do you do?',
    'أثناء جولة ميدانية ترى على صمام بطاقة تحمل رقم أمر عمل مختلف عن الأمر الموجود في حزمتك. تقول غرفة التحكم إن البطاقة على الأرجح متبقية من الأسبوع الماضي. ماذا تفعل؟',
    [O('Carry on with the task; the control room has explained it.', 'تواصل المهمة؛ فقد قدّمت غرفة التحكم تفسيراً.', 1, '"Probably" is an assumption, not a verified fact.', 'كلمة "على الأرجح" افتراض وليست حقيقة مؤكدة.'),
      O('Stop the work on that valve and ask work control to confirm the tag against the clearance record.', 'توقف العمل على ذلك الصمام وتطلب من التحكم في العمل تأكيد البطاقة مقابل سجل التصاريح.', 3, 'Checks the fact with the record that owns it before acting.', 'يتحقق من الحقيقة من السجل المسؤول عنها قبل التصرف.'),
      O('Remove the old tag so it does not confuse the next team.', 'تزيل البطاقة القديمة كي لا تربك الفريق التالي.', 0, 'Removing a tag yourself changes plant configuration without authority.', 'إزالة البطاقة بنفسك تغيّر وضع المحطة دون صلاحية.'),
      O('Do the steps that do not involve that valve and raise the tag at the next break.', 'تنفّذ الخطوات التي لا تتعلق بذلك الصمام وتثير موضوع البطاقة في الاستراحة التالية.', 2, 'Protects the affected step, but leaves the question open for too long.', 'يحمي الخطوة المتأثرة لكنه يترك السؤال معلقاً مدة طويلة.')],
    'A tag that does not match the package means the plant may not be in the state you think. The expert response stops the work that depends on it and checks the clearance record, the source that owns the fact. Acting on someone\'s "probably" is exactly the assumption a questioning attitude exists to challenge.',
    'البطاقة التي لا تطابق الحزمة تعني أن المحطة قد لا تكون في الحالة التي تظنها. الاستجابة الأفضل توقف العمل المعتمد عليها وتتحقق من سجل التصاريح، المصدر المسؤول عن الحقيقة. التصرف بناءً على "على الأرجح" هو بالضبط الافتراض الذي وُجد موقف التساؤل لتحدّيه.'),
  I('cs-questioning', 'questioning',
    'A trend chart shows a bearing temperature flat at exactly the same value for six hours, while the pump has been running hard. Everyone in the briefing says the pump is fine. What do you do?',
    'يُظهر مخطط الاتجاه حرارة محمل ثابتة عند القيمة نفسها تماماً لست ساعات، بينما كانت المضخة تعمل بحمل عالٍ. الجميع في الإحاطة يقولون إن المضخة بخير. ماذا تفعل؟',
    [O('Agree; a steady temperature is a good sign.', 'توافق؛ فالحرارة الثابتة علامة جيدة.', 0, 'A perfectly flat value on a working machine often means a failed sensor.', 'القيمة الثابتة تماماً على آلة تعمل تعني غالباً حساساً معطلاً.'),
      O('Ask whether the sensor is live and request a local reading to compare.', 'تسأل إن كان الحساس يعمل وتطلب قراءة ميدانية للمقارنة.', 3, 'Names the specific doubt and checks it with an independent indication.', 'يحدد موضع الشك ويتحقق منه بمؤشر مستقل.'),
      O('Mention it after the meeting to the engineer you trust most.', 'تذكر ذلك بعد الاجتماع للمهندس الذي تثق به أكثر.', 1, 'The doubt is raised, but not where the decision is being made.', 'يُطرح الشك لكن ليس حيث يُتخذ القرار.'),
      O('Raise it in the briefing as a question and leave it to the shift manager.', 'تطرحه في الإحاطة سؤالاً وتترك الأمر لمدير الوردية.', 2, 'Right forum, but without proposing how to check it.', 'المكان المناسب، لكن دون اقتراح طريقة للتحقق.')],
    'Questioning attitude means noticing what does not fit, here a value too perfect for a running machine, and checking it with an independent indication. Silence because "everyone agrees" is the group-think that operating experience warns about.',
    'موقف التساؤل يعني ملاحظة ما لا يتّسق، وهنا قيمة مثالية أكثر من اللازم لآلة تعمل، والتحقق منها بمؤشر مستقل. الصمت لأن "الجميع متفقون" هو التفكير الجماعي الذي تحذّر منه الخبرة التشغيلية.'),
  I('cs-questioning', 'digital_judgement',
    'An approved document assistant gives you the torque value for a flange from a procedure. The value looks lower than you remember. What do you do?',
    'يعطيك مساعد الوثائق المعتمد قيمة عزم الربط لشفة من أحد الإجراءات. تبدو القيمة أقل مما تتذكر. ماذا تفعل؟',
    [O('Open the cited controlled procedure and check the value and its revision.', 'تفتح الإجراء المضبوط المستشهد به وتتحقق من القيمة ومن رقم المراجعة.', 3, 'Goes to the controlled source, the only thing you may rely on.', 'يذهب إلى المصدر المضبوط، وهو الوحيد الذي يجوز الاعتماد عليه.'),
      O('Use the assistant\'s value; it read the procedure.', 'تستخدم قيمة المساعد؛ فقد قرأ الإجراء.', 0, 'An AI summary is never the controlled document.', 'ملخص الذكاء الاصطناعي ليس الوثيقة المضبوطة أبداً.'),
      O('Use the value you remember.', 'تستخدم القيمة التي تتذكرها.', 0, 'Memory is no better than the tool; neither is controlled.', 'الذاكرة ليست أفضل من الأداة؛ فكلاهما غير مضبوط.'),
      O('Ask a colleague which value is right.', 'تسأل زميلاً عن القيمة الصحيحة.', 1, 'A second opinion is not the controlled source.', 'الرأي الثاني ليس المصدر المضبوط.')],
    'When a tool and your memory disagree, neither wins: the controlled procedure does. The expert response opens the cited source, checks the revision and uses only that value.',
    'عندما تختلف الأداة مع ذاكرتك فلا يكسب أيّ منهما: الإجراء المضبوط هو المرجع. الاستجابة الأفضل تفتح المصدر المستشهد به وتتحقق من المراجعة وتستخدم تلك القيمة وحدها.'),

  // ───────────── TC-2 Conservative decision-making
  I('cs-conservative', 'conservative_decisions',
    'Near the end of a planned power increase, an indication you cannot explain appears on a secondary system. The schedule is tight and the grid dispatcher is waiting. What do you recommend?',
    'قرب نهاية زيادة مخطط لها في القدرة، يظهر مؤشر لا تستطيع تفسيره على نظام ثانوي. الجدول ضيق ومشغّل الشبكة ينتظر. بماذا توصي؟',
    [O('Continue the increase and investigate in parallel.', 'مواصلة الزيادة والتحقيق بالتوازي.', 0, 'Keeps changing the plant while the cause is unknown.', 'يستمر في تغيير وضع المحطة والسبب مجهول.'),
      O('Hold power where it is, investigate, and resume only once the indication is understood.', 'تثبيت القدرة عند مستواها، والتحقيق، والاستئناف فقط بعد فهم المؤشر.', 3, 'Keeps the plant in a known state until the uncertainty is resolved.', 'يُبقي المحطة في حالة معروفة حتى تُحل حالة عدم اليقين.'),
      O('Reduce power sharply as a precaution.', 'خفض القدرة بشكل حاد على سبيل الاحتياط.', 1, 'A large unplanned change is itself a new risk when a hold would do.', 'التغيير الكبير غير المخطط له خطر جديد بحد ذاته حين يكفي التثبيت.'),
      O('Ask the dispatcher how long they can wait, then decide.', 'تسأل مشغّل الشبكة كم يستطيع الانتظار ثم تقرر.', 1, 'Lets external pressure shape a safety decision.', 'يجعل الضغط الخارجي يحدد قرار سلامة.')],
    'Conservative decision-making chooses the action that keeps the plant in a known, safe state while something is not understood. Holding is the conservative choice; continuing trades margin for schedule, and a sharp reduction creates a new transient without need.',
    'اتخاذ القرار المحافظ يختار الإجراء الذي يُبقي المحطة في حالة آمنة معروفة ما دام هناك أمر غير مفهوم. التثبيت هو الخيار المحافظ؛ أما المواصلة فتقايض هامش السلامة بالجدول، والخفض الحاد يُحدث حالة عابرة جديدة دون حاجة.'),
  I('cs-conservative', 'conservative_decisions',
    'A maintenance job is ready to start, but one prerequisite in the work package is signed by someone who was not on site that day. The supervisor says it is a paperwork slip. What do you do?',
    'عمل صيانة جاهز للبدء، لكن أحد المتطلبات المسبقة في حزمة العمل موقّع من شخص لم يكن في الموقع ذلك اليوم. يقول المشرف إنها هفوة ورقية. ماذا تفعل؟',
    [O('Start; the supervisor has accepted it.', 'تبدأ؛ فقد قبل المشرف ذلك.', 0, 'An unverified prerequisite is treated as met.', 'يُعامَل متطلب غير مؤكد كأنه مستوفى.'),
      O('Do not start until the prerequisite is verified or re-performed and properly signed.', 'لا تبدأ حتى يُتحقق من المتطلب أو يُعاد تنفيذه ويُوقَّع بشكل صحيح.', 3, 'Treats the condition as unknown until it is proven.', 'يعامل الشرط على أنه غير معروف حتى يثبت.'),
      O('Start the parts of the job that do not depend on that prerequisite.', 'تبدأ أجزاء العمل التي لا تعتمد على ذلك المتطلب.', 2, 'Reasonable if the independence is clear, but it splits the package informally.', 'معقول إن كان الاستقلال واضحاً، لكنه يجزّئ الحزمة بشكل غير رسمي.'),
      O('Fix the signature yourself so the record is right.', 'تصحح التوقيع بنفسك كي يصبح السجل صحيحاً.', 0, 'Falsifies a record; never acceptable.', 'تزوير للسجل؛ غير مقبول أبداً.')],
    'If you cannot trust that a prerequisite was done, assume it was not. The expert response waits until it is verified or re-done and properly signed. A record is evidence of a plant condition, so "paperwork slips" in prerequisites are plant questions, not clerical ones.',
    'إذا لم تستطع الوثوق بأن متطلباً قد نُفِّذ، فافترض أنه لم يُنفَّذ. الاستجابة الأفضل تنتظر حتى يُتحقق منه أو يُعاد ويُوقَّع بشكل صحيح. السجل دليل على حالة المحطة، لذا فإن "الهفوات الورقية" في المتطلبات المسبقة أسئلة تخص المحطة لا أعمالاً كتابية.'),
  I('cs-conservative', 'teamwork_pressure',
    'In the simulator, your crew can either follow a slower recovery path that keeps more margin or a faster one that saves twenty minutes but uses most of the margin. The instructor is timing you. What do you choose?',
    'في المحاكي، يمكن لطاقمك اتباع مسار تعافٍ أبطأ يحافظ على هامش أكبر، أو مسار أسرع يوفر عشرين دقيقة لكنه يستهلك معظم الهامش. المدرب يقيس الوقت. ماذا تختار؟',
    [O('The faster path; the time is being measured.', 'المسار الأسرع؛ فالوقت يُقاس.', 0, 'Optimises the wrong thing.', 'يحسّن الشيء الخطأ.'),
      O('The slower path, saying why to the crew.', 'المسار الأبطأ، مع شرح السبب للطاقم.', 3, 'Keeps margin and makes the reasoning shared.', 'يحافظ على الهامش ويجعل التفكير مشتركاً.'),
      O('Ask the instructor which path they want.', 'تسأل المدرب أي مسار يريد.', 1, 'Hands off a decision the crew owns.', 'يتخلى عن قرار يملكه الطاقم.'),
      O('The slower path, without discussing it.', 'المسار الأبطأ دون نقاش.', 2, 'Right choice, but the crew does not learn why.', 'الخيار الصحيح، لكن الطاقم لا يتعلّم السبب.')],
    'Practice is where habits form. Choosing margin over speed, and saying why, builds the crew habit that counts on a real shift. A stopwatch is not a safety goal.',
    'التمرين هو المكان الذي تتشكّل فيه العادات. اختيار الهامش على السرعة مع ذكر السبب يبني عادة الطاقم التي يُعتمد عليها في وردية حقيقية. ساعة الإيقاف ليست هدفاً للسلامة.'),

  // ───────────── TC-3 Procedure use and knowing when to stop
  I('cs-procedure', 'procedure_use',
    'At step 14 of a procedure, the pump should start and the discharge pressure should rise. The pump starts, but the pressure does not change. What do you do?',
    'في الخطوة 14 من إجراء ما، يُفترض أن تبدأ المضخة وأن يرتفع ضغط التصريف. تبدأ المضخة لكن الضغط لا يتغيّر. ماذا تفعل؟',
    [O('Continue to step 15; the pump did start.', 'تنتقل إلى الخطوة 15؛ فالمضخة بدأت فعلاً.', 0, 'The expected result did not happen, so the procedure no longer fits.', 'لم تحدث النتيجة المتوقعة، فلم يعد الإجراء مناسباً.'),
      O('Stop, put the system in a safe condition as the procedure allows, and call the supervisor.', 'تتوقف وتضع النظام في حالة آمنة كما يسمح الإجراء وتتصل بالمشرف.', 3, 'Stops at the deviation and gets help with the plant safe.', 'يتوقف عند الانحراف ويطلب المساعدة مع إبقاء المحطة آمنة.'),
      O('Restart the pump once to see if it helps.', 'تعيد تشغيل المضخة مرة واحدة لترى إن كان ذلك يساعد.', 0, 'An action the procedure does not call for.', 'إجراء لا يطلبه الإجراء المكتوب.'),
      O('Wait a few minutes for the pressure to come up, then decide.', 'تنتظر بضع دقائق حتى يرتفع الضغط ثم تقرر.', 1, 'Waiting without placing the system safe is drifting, not stopping.', 'الانتظار دون وضع النظام في حالة آمنة انجراف وليس توقفاً.')],
    'Procedures say what should happen. When it does not, the procedure no longer describes the plant, so you stop with the plant safe and get help. Improvising, even "just one restart", is how small deviations become events.',
    'تقول الإجراءات ما يجب أن يحدث. وعندما لا يحدث، لم يعد الإجراء يصف المحطة، فتتوقف مع إبقاء المحطة آمنة وتطلب المساعدة. الارتجال، ولو كان "إعادة تشغيل واحدة فقط"، هو ما يحوّل الانحرافات الصغيرة إلى أحداث.'),
  I('cs-procedure', 'procedure_use',
    'You find that a procedure refers to a valve number that has been renamed since a modification. The intent is obvious. What do you do?',
    'تكتشف أن إجراءً يشير إلى رقم صمام تغيّر اسمه بعد تعديل. المقصود واضح. ماذا تفعل؟',
    [O('Use the new valve; the intent is obvious.', 'تستخدم الصمام الجديد؛ فالمقصود واضح.', 1, 'Probably right, but you are now working outside the written procedure.', 'غالباً صحيح، لكنك الآن تعمل خارج الإجراء المكتوب.'),
      O('Stop and get the procedure corrected or a documented change approved before continuing.', 'تتوقف وتطلب تصحيح الإجراء أو اعتماد تغيير موثّق قبل المتابعة.', 3, 'Keeps the work inside an approved document and fixes it for others.', 'يُبقي العمل ضمن وثيقة معتمدة ويصحّحها للآخرين.'),
      O('Write the new number in the margin and carry on.', 'تكتب الرقم الجديد في الهامش وتواصل.', 0, 'An unapproved pen-and-ink change.', 'تعديل يدوي غير معتمد.'),
      O('Skip the step and report it afterwards.', 'تتخطى الخطوة وتبلغ عنها لاحقاً.', 0, 'Skipping a step is never a fix.', 'تخطي الخطوة ليس حلاً أبداً.')],
    'Even when the intent is obvious, a procedure that does not match the plant must be corrected through the approved route before use. The expert response stops and gets the change approved, so the next person does not face the same gap.',
    'حتى عندما يكون المقصود واضحاً، يجب تصحيح الإجراء الذي لا يطابق المحطة عبر المسار المعتمد قبل استخدامه. الاستجابة الأفضل تتوقف وتطلب اعتماد التغيير، كي لا يواجه الشخص التالي الفجوة نفسها.'),
  I('cs-procedure', 'teamwork_pressure',
    'A senior colleague tells you to skip the place-keeping marks on a routine procedure because "we have done this a hundred times". What do you do?',
    'يطلب منك زميل أقدم تخطي علامات تتبّع الموضع في إجراء روتيني لأننا "فعلنا هذا مئة مرة". ماذا تفعل؟',
    [O('Keep marking each step and say briefly why.', 'تواصل تأشير كل خطوة وتوضح السبب باختصار.', 3, 'Keeps the defence in place and explains it respectfully.', 'يُبقي خط الدفاع قائماً ويشرح السبب باحترام.'),
      O('Stop marking; they are more experienced.', 'تتوقف عن التأشير؛ فهو أكثر خبرة.', 0, 'Familiarity is the condition where place-keeping matters most.', 'الألفة هي الحالة التي يصبح فيها تتبّع الموضع أهم ما يكون.'),
      O('Mark only the critical steps.', 'تؤشّر الخطوات الحرجة فقط.', 1, 'A self-made exception to the standard.', 'استثناء ذاتي من المعيار.'),
      O('Keep marking and report the colleague to the manager.', 'تواصل التأشير وتبلغ المدير عن الزميل.', 2, 'Right practice, but escalation before a conversation may be early.', 'الممارسة صحيحة، لكن التصعيد قبل الحوار قد يكون مبكراً.')],
    'Routine work is where slips happen, which is why place-keeping exists. The best response keeps the standard and explains it, which also helps the colleague. Escalate if the pressure continues.',
    'العمل الروتيني هو حيث تقع الهفوات، ولهذا وُجد تتبّع الموضع. الاستجابة الأفضل تحافظ على المعيار وتشرحه، مما يساعد الزميل أيضاً. صعّد الأمر إذا استمر الضغط.'),

  // ───────────── TC-4 Systems thinking
  I('cs-systems', 'questioning',
    'You are about to isolate a small cooling pump for maintenance. The isolation looks simple and only affects your system on the drawing. What do you check first?',
    'أنت على وشك عزل مضخة تبريد صغيرة للصيانة. يبدو العزل بسيطاً ولا يؤثر على المخطط إلا على نظامك. ما الذي تتحقق منه أولاً؟',
    [O('Nothing more; the drawing shows no other effects.', 'لا شيء آخر؛ فالمخطط لا يُظهر آثاراً أخرى.', 0, 'One drawing rarely shows every interface.', 'نادراً ما يُظهر مخطط واحد جميع الواجهات.'),
      O('Which other loads share the same power supply and cooling, and who else is working on them today.', 'الأحمال الأخرى التي تتشارك مصدر الطاقة والتبريد نفسه، ومن يعمل عليها اليوم.', 3, 'Looks for hidden couplings across systems and teams.', 'يبحث عن الترابطات الخفية عبر الأنظمة والفرق.'),
      O('That the pump is the right one, by its label.', 'أن المضخة هي الصحيحة من خلال ملصقها.', 2, 'Necessary, but it only covers your own component.', 'ضروري، لكنه يغطي مكوّنك فقط.'),
      O('That the isolation is on today\'s schedule.', 'أن العزل مدرج في جدول اليوم.', 1, 'Scheduling is not the same as understanding effects.', 'الجدولة ليست فهماً للآثار.')],
    'Systems thinking means looking past your own component: shared supplies, shared cooling and parallel work are where simple isolations surprise people. The expert response checks those couplings first.',
    'التفكير المنظومي يعني النظر أبعد من مكوّنك: مصادر الطاقة المشتركة والتبريد المشترك والأعمال المتوازية هي حيث تفاجئ العزلات البسيطة الناس. الاستجابة الأفضل تتحقق من هذه الترابطات أولاً.'),
  I('cs-systems', 'learning_change',
    'A proposed change to a ventilation setpoint will cut energy use. You are asked to review it from your discipline only. What do you do?',
    'تغيير مقترح على نقطة ضبط للتهوية سيخفض استهلاك الطاقة. يُطلب منك مراجعته من منظور تخصصك فقط. ماذا تفعل؟',
    [O('Review your discipline only, as asked.', 'تراجع تخصصك فقط كما طُلب.', 1, 'Meets the request but may miss cross-system effects.', 'يلبي الطلب لكنه قد يُغفل آثاراً عبر الأنظمة.'),
      O('Review your part and list the other systems the change may affect, asking for their reviewers.', 'تراجع الجزء الخاص بك وتسرد الأنظمة الأخرى التي قد يؤثر عليها التغيير وتطلب مراجعيها.', 3, 'Does the job and makes the hidden interfaces visible.', 'ينجز المهمة ويجعل الواجهات الخفية مرئية.'),
      O('Approve it; energy savings are a company goal.', 'توافق عليه؛ فتوفير الطاقة هدف للشركة.', 0, 'A goal is not a technical review.', 'الهدف ليس مراجعة فنية.'),
      O('Reject it until every discipline has reviewed it.', 'ترفضه حتى تراجعه جميع التخصصات.', 2, 'Cautious, but blocks rather than routing the review.', 'حذر، لكنه يعرقل بدلاً من توجيه المراجعة.')],
    'Changes interact. A good reviewer does their part and points to the interfaces nobody asked about, such as room temperatures, equipment qualification and habitability. That is how systems thinking adds value without slowing everything.',
    'التغييرات تتفاعل. المراجع الجيد ينجز جزءه ويشير إلى الواجهات التي لم يسأل عنها أحد، مثل حرارة الغرف وتأهيل المعدات وصلاحية الأماكن للإشغال. هكذا يضيف التفكير المنظومي قيمة دون إبطاء كل شيء.'),
  I('cs-systems', 'teamwork_pressure',
    'Two teams want the same crane on the same morning during an outage. Each says its job is critical. You coordinate the work. What do you do first?',
    'يريد فريقان الرافعة نفسها صباح اليوم نفسه أثناء الانقطاع، ويقول كل منهما إن عمله حرج. أنت منسق العمل. ماذا تفعل أولاً؟',
    [O('Give it to the team that asked first.', 'تمنحها للفريق الذي طلب أولاً.', 0, 'Order of asking says nothing about risk or the critical path.', 'ترتيب الطلب لا يدل على الخطر ولا على المسار الحرج.'),
      O('Look at both jobs on the outage critical path and the risk of each delay, then decide with both leads.', 'تنظر إلى العملين على المسار الحرج للانقطاع وخطر تأخير كل منهما، ثم تقرر مع قائدي الفريقين.', 3, 'Decides on the whole-system effect, transparently.', 'يقرر بناءً على الأثر في المنظومة كلها وبشفافية.'),
      O('Split the morning in half.', 'تقسم الصباح مناصفة.', 1, 'Looks fair, but may delay both critical jobs.', 'يبدو عادلاً لكنه قد يؤخر العملين الحرجين معاً.'),
      O('Escalate to the outage manager immediately.', 'تصعّد فوراً إلى مدير الانقطاع.', 2, 'Sometimes right, but first gather the facts they will need.', 'صحيح أحياناً، لكن اجمع أولاً الوقائع التي سيحتاجها.')],
    'Systems thinking in coordination means judging work by its effect on the whole outage, critical path and risk, not by who asks first or loudest. Deciding with both leads keeps the trade-off visible.',
    'التفكير المنظومي في التنسيق يعني الحكم على العمل بأثره في الانقطاع كله، أي المسار الحرج والمخاطر، لا بمن طلب أولاً أو بصوت أعلى. اتخاذ القرار مع القائدين يُبقي المفاضلة واضحة.'),

  // ───────────── TC-5 Problem identification and resolution
  I('cs-problem', 'questioning',
    'An alarm has come in on several night shifts and each crew has acknowledged and reset it. Nothing has gone wrong yet. What do you do?',
    'ظهر إنذار في عدة ورديات ليلية وكل طاقم أقرّ به وأعاد ضبطه. لم يحدث أي خلل حتى الآن. ماذا تفعل؟',
    [O('Reset it like the other crews; it is clearly a nuisance alarm.', 'تعيد ضبطه كما فعلت الأطقم الأخرى؛ فهو بوضوح إنذار مزعج.', 0, 'Normalises a signal nobody has explained.', 'يطبّع إشارة لم يفسّرها أحد.'),
      O('Raise a condition report with the times and conditions, and ask for a cause evaluation.', 'ترفع تقرير حالة بالأوقات والظروف وتطلب تقييماً للسبب.', 3, 'Turns a repeated symptom into a problem someone owns.', 'يحوّل عرضاً متكرراً إلى مشكلة لها مالك.'),
      O('Note it in the shift log for the day crew.', 'تدوّنه في سجل الوردية لطاقم النهار.', 1, 'Recorded, but not in the system that drives a fix.', 'مسجّل، لكن ليس في النظام الذي يقود إلى الإصلاح.'),
      O('Ask maintenance informally to have a look when they can.', 'تطلب من الصيانة بشكل غير رسمي أن تلقي نظرة حين تستطيع.', 1, 'Informal requests are easily lost.', 'الطلبات غير الرسمية تضيع بسهولة.')],
    'Repeated alarms that everyone resets are a classic precursor. The corrective action programme exists so that patterns get an owner and a cause. Report it with facts and ask for evaluation.',
    'الإنذارات المتكررة التي يعيد الجميع ضبطها مؤشر كلاسيكي على ما قد يأتي. وُجد برنامج الإجراءات التصحيحية كي يكون للأنماط مالك وسبب. أبلغ عنها بالوقائع واطلب التقييم.'),
  I('cs-problem', 'learning_change',
    'A corrective action from last year was closed as "procedure revised", but you see the same error happening again. What do you do?',
    'أُغلق إجراء تصحيحي من العام الماضي بعبارة "عُدِّل الإجراء"، لكنك ترى الخطأ نفسه يتكرر. ماذا تفعل؟',
    [O('Nothing; the action is closed.', 'لا شيء؛ فالإجراء مغلق.', 0, 'Closed is not the same as effective.', 'الإغلاق لا يعني الفعالية.'),
      O('Report the recurrence and ask for an effectiveness review of the original action.', 'تبلغ عن التكرار وتطلب مراجعة لفعالية الإجراء الأصلي.', 3, 'Checks whether the fix addressed the cause.', 'يتحقق مما إذا كان الإصلاح قد عالج السبب.'),
      O('Remind your team to be more careful.', 'تذكّر فريقك بأن يكونوا أكثر حذراً.', 1, 'Addresses people, not the cause.', 'يعالج الأشخاص لا السبب.'),
      O('Raise a new report without linking it to the old one.', 'ترفع تقريراً جديداً دون ربطه بالقديم.', 2, 'Good to report, but the pattern is lost.', 'الإبلاغ جيد، لكن النمط يضيع.')],
    'Good problem resolution checks that fixes worked. A recurrence after closure is evidence that the cause was not addressed, and linking it to the original action is what lets the organisation learn.',
    'الحل الجيد للمشكلات يتحقق من نجاح الإصلاحات. التكرار بعد الإغلاق دليل على أن السبب لم يُعالَج، وربطه بالإجراء الأصلي هو ما يتيح للمؤسسة أن تتعلّم.'),
  I('cs-problem', 'digital_judgement',
    'A data dashboard shows that a team\'s error rate has dropped to zero this month. The team is new to the reporting tool. What is the best interpretation?',
    'تُظهر لوحة بيانات أن معدل أخطاء أحد الفرق انخفض إلى الصفر هذا الشهر. الفريق جديد على أداة الإبلاغ. ما التفسير الأفضل؟',
    [O('The team has improved; share it as good practice.', 'تحسّن الفريق؛ شارك ذلك ممارسةً جيدة.', 0, 'Jumps to the flattering conclusion.', 'يقفز إلى الاستنتاج المريح.'),
      O('Check whether the team is reporting through the new tool before drawing a conclusion.', 'تتحقق مما إذا كان الفريق يبلغ عبر الأداة الجديدة قبل استخلاص أي نتيجة.', 3, 'Tests the data before trusting the trend.', 'يختبر البيانات قبل الوثوق بالاتجاه.'),
      O('Ignore it; one month means nothing.', 'تتجاهله؛ فشهر واحد لا يعني شيئاً.', 1, 'Dismisses a signal that deserves a check.', 'يتجاهل إشارة تستحق التحقق.'),
      O('Ask the team leader if the number is right.', 'تسأل قائد الفريق إن كان الرقم صحيحاً.', 2, 'A reasonable step, but checking the data directly is stronger.', 'خطوة معقولة، لكن التحقق من البيانات مباشرة أقوى.')],
    'A sudden zero after a tool change is more often a reporting gap than a real improvement. Identify the problem correctly by checking the data source before acting on the trend.',
    'الصفر المفاجئ بعد تغيير الأداة يكون في الغالب فجوة في الإبلاغ لا تحسناً حقيقياً. حدّد المشكلة بدقة بالتحقق من مصدر البيانات قبل التصرف بناءً على الاتجاه.'),

  // ───────────── TC-6 Creative thinking and improvement
  I('cs-creative', 'learning_change',
    'You have an idea for a clearer turnover sheet that you think would cut handover errors. What is the best next step?',
    'لديك فكرة لنموذج تسليم أوضح تعتقد أنه سيقلل أخطاء التسليم. ما الخطوة التالية الأفضل؟',
    [O('Start using your version on your shift.', 'تبدأ باستخدام نسختك في ورديتك.', 0, 'An uncontrolled document on shift.', 'وثيقة غير مضبوطة أثناء الوردية.'),
      O('Draft it, gather a few examples of the errors, and submit it through the change process with an offer to pilot it.', 'تعدّ مسودة وتجمع أمثلة على الأخطاء، وتقدّمها عبر عملية التغيير مع عرض لتجربتها.', 3, 'Combines the idea, evidence and the proper route.', 'يجمع الفكرة والأدلة والمسار الصحيح.'),
      O('Mention it to your manager when you next meet.', 'تذكرها لمديرك في لقائكما القادم.', 1, 'Raised, but without evidence or a route.', 'طُرحت لكن دون أدلة أو مسار.'),
      O('Post it in the community of practice for comments first.', 'تنشرها في مجتمع الممارسة للتعليق أولاً.', 2, 'Useful feedback, but it still needs the change process.', 'تغذية راجعة مفيدة، لكنها لا تزال تحتاج عملية التغيير.')],
    'At a nuclear plant, creativity runs through the change process. The best response pairs the idea with evidence and offers a controlled pilot, so a good idea becomes an approved improvement.',
    'في المحطة النووية يمر الإبداع عبر عملية التغيير. الاستجابة الأفضل تقرن الفكرة بالأدلة وتعرض تجربة مضبوطة، فتتحول الفكرة الجيدة إلى تحسين معتمد.'),
  I('cs-creative', 'teamwork_pressure',
    'In a team meeting, a junior colleague suggests a new way to sequence outage tasks. Others laugh it off. You lead the meeting. What do you do?',
    'في اجتماع للفريق، يقترح زميل حديث طريقة جديدة لترتيب مهام الانقطاع. يتجاهلها الآخرون ضاحكين. أنت تدير الاجتماع. ماذا تفعل؟',
    [O('Move on; there is no time today.', 'تنتقل إلى البند التالي؛ فلا وقت اليوم.', 0, 'Teaches the team that ideas are not welcome.', 'يعلّم الفريق أن الأفكار غير مرحّب بها.'),
      O('Ask the colleague to explain the idea briefly, and agree how it will be looked at properly.', 'تطلب من الزميل شرح الفكرة باختصار وتتفق على كيفية دراستها بشكل صحيح.', 3, 'Gives the idea a fair hearing and a route.', 'يمنح الفكرة استماعاً عادلاً ومساراً.'),
      O('Tell the others to be respectful and move on.', 'تطلب من الآخرين الاحترام وتنتقل.', 1, 'Protects the person but not the idea.', 'يحمي الشخص لكن ليس الفكرة.'),
      O('Promise to look at it yourself later.', 'تعد بأن تنظر فيها بنفسك لاحقاً.', 2, 'Better than nothing, but private and easily forgotten.', 'أفضل من لا شيء، لكنه خاص ويُنسى بسهولة.')],
    'Improvement depends on ideas being heard, especially from people new enough to see things freshly. The leader\'s job is to give the idea a fair hearing and a proper route, not to judge it on the spot.',
    'يعتمد التحسين على الاستماع إلى الأفكار، خاصة من الجدد القادرين على رؤية الأمور بعين جديدة. دور القائد أن يمنح الفكرة استماعاً عادلاً ومساراً صحيحاً، لا أن يحكم عليها فوراً.'),
  I('cs-creative', 'digital_judgement',
    'You want to try an approved AI assistant to draft routine weekly status reports for your team. What is the best way to start?',
    'تريد تجربة مساعد ذكاء اصطناعي معتمد لصياغة تقارير الحالة الأسبوعية الروتينية لفريقك. ما أفضل طريقة للبدء؟',
    [O('Use it from next week and see how it goes.', 'تستخدمه ابتداءً من الأسبوع القادم وترى كيف تسير الأمور.', 1, 'No agreed checks or review point.', 'لا توجد ضوابط متفق عليها ولا نقطة مراجعة.'),
      O('Run a short pilot with a person reviewing every draft, and agree with the team what the tool may and may not draft.', 'تجري تجربة قصيرة يراجع فيها شخص كل مسودة، وتتفق مع الفريق على ما يجوز للأداة صياغته وما لا يجوز.', 3, 'A small, governed trial with people in charge.', 'تجربة صغيرة محوكمة يبقى فيها الإنسان مسؤولاً.'),
      O('Wait until another team has tried it.', 'تنتظر حتى يجربه فريق آخر.', 1, 'Safe, but no learning happens.', 'آمن، لكن لا يحدث أي تعلّم.'),
      O('Use it for the reports and the shift logs to save more time.', 'تستخدمه للتقارير وسجلات الوردية لتوفير وقت أكثر.', 0, 'Extends use to records that need tighter control.', 'يوسّع الاستخدام إلى سجلات تحتاج ضبطاً أشد.')],
    'Trying new tools is good; doing it as a small, governed pilot with human review and clear limits is how innovation stays safe.',
    'تجربة الأدوات الجديدة أمر جيد؛ والقيام بذلك عبر تجربة صغيرة محوكمة مع مراجعة بشرية وحدود واضحة هو ما يُبقي الابتكار آمناً.'),

  // ───────────── IO-1 Peer checking
  I('cs-peer-check', 'teamwork_pressure',
    'You are peer-checking a colleague who is about to open a breaker. They point at it and say "this one, right?" while reading the label to you. What do you do?',
    'تتحقق مع زميل على وشك فتح قاطع. يشير إليه ويقول "هذا هو، صحيح؟" بينما يقرأ لك الملصق. ماذا تفعل؟',
    [O('Say "yes" since they read the label.', 'تقول "نعم" لأنه قرأ الملصق.', 0, 'You checked their reading, not the component.', 'تحققت من قراءته لا من المكوّن.'),
      O('Read the label yourself against your own copy of the work document before agreeing.', 'تقرأ الملصق بنفسك مقابل نسختك من وثيقة العمل قبل الموافقة.', 3, 'An independent check: own eyes, own reference.', 'تحقق مستقل: بعينيك ومرجعك الخاص.'),
      O('Ask them to read it again more slowly.', 'تطلب منه قراءته مرة أخرى ببطء أكثر.', 1, 'Still depends on their reading.', 'لا يزال يعتمد على قراءته.'),
      O('Check the breaker position indicator only.', 'تتحقق من مؤشر وضع القاطع فقط.', 1, 'Position is not identity.', 'الوضع ليس الهوية.')],
    'A peer check only adds protection if it is independent. Confirming what a colleague says turns two people into one. Read the component yourself against your own reference.',
    'لا يضيف التحقق المتبادل حماية إلا إذا كان مستقلاً. تأكيد ما يقوله الزميل يحوّل شخصين إلى شخص واحد. اقرأ المكوّن بنفسك مقابل مرجعك الخاص.'),
  I('cs-peer-check', 'teamwork_pressure',
    'A very experienced technician looks annoyed when you ask to peer-check a critical step. What do you do?',
    'يبدو فني ذو خبرة طويلة منزعجاً عندما تطلب التحقق المتبادل في خطوة حرجة. ماذا تفعل؟',
    [O('Skip the check to keep the peace.', 'تتخطى التحقق حفاظاً على الود.', 0, 'Removes a barrier because of a feeling.', 'يزيل خط دفاع بسبب شعور.'),
      O('Do the check calmly and say it is the standard for everyone on critical steps.', 'تجري التحقق بهدوء وتوضح أنه المعيار للجميع في الخطوات الحرجة.', 3, 'Keeps the barrier and depersonalises it.', 'يحافظ على خط الدفاع ويبعده عن الطابع الشخصي.'),
      O('Do the check quickly so it does not take long.', 'تجري التحقق بسرعة كي لا يستغرق وقتاً.', 1, 'A rushed check is a weak check.', 'التحقق المتعجّل تحقق ضعيف.'),
      O('Ask your supervisor to tell the technician to accept checks.', 'تطلب من مشرفك أن يطلب من الفني تقبّل التحقق.', 2, 'May help later, but the check still has to happen now.', 'قد يفيد لاحقاً، لكن التحقق يجب أن يحدث الآن.')],
    'Experience does not remove the need for peer checks on critical steps; experienced people make fewer errors, not none. Doing the check calmly and naming it as the standard keeps both the barrier and the relationship.',
    'الخبرة لا تلغي الحاجة إلى التحقق المتبادل في الخطوات الحرجة؛ فأصحاب الخبرة يخطئون أقل لا أنهم لا يخطئون. إجراء التحقق بهدوء ووصفه بأنه المعيار يحافظ على خط الدفاع وعلى العلاقة معاً.'),
  I('cs-peer-check', 'procedure_use',
    'During a pre-job brief, the crew agrees which steps need a peer check. Halfway through the job, the plan changes and a new critical step is added. What do you do?',
    'خلال إحاطة ما قبل العمل، يتفق الطاقم على الخطوات التي تحتاج تحققاً متبادلاً. في منتصف العمل تتغيّر الخطة وتُضاف خطوة حرجة جديدة. ماذا تفعل؟',
    [O('Continue; the brief already covered peer checks.', 'تواصل؛ فالإحاطة تناولت التحقق المتبادل مسبقاً.', 0, 'The brief did not cover this step.', 'لم تتناول الإحاطة هذه الخطوة.'),
      O('Pause, re-brief the new step and agree who checks it.', 'تتوقف مؤقتاً وتعيد الإحاطة بالخطوة الجديدة وتتفق على من يتحقق منها.', 3, 'Brings the new risk into the team\'s plan.', 'يدخل الخطر الجديد في خطة الفريق.'),
      O('Peer-check it yourself without telling the others.', 'تتحقق منها بنفسك دون إخبار الآخرين.', 1, 'Helpful, but the crew does not share the picture.', 'مفيد، لكن الطاقم لا يتشارك الصورة.'),
      O('Ask the supervisor whether a check is needed.', 'تسأل المشرف إن كان التحقق لازماً.', 2, 'Reasonable, but the crew can re-brief directly.', 'معقول، لكن يمكن للطاقم إعادة الإحاطة مباشرة.')],
    'Peer checks are planned in the brief; when the job changes, the plan must change too. A short re-brief keeps the whole crew aligned on the new critical step.',
    'يُخطَّط للتحقق المتبادل في الإحاطة؛ وعندما يتغيّر العمل يجب أن تتغيّر الخطة أيضاً. إعادة إحاطة قصيرة تُبقي الطاقم كله متوافقاً على الخطوة الحرجة الجديدة.'),

  // ───────────── IO-2 Communication under stress
  I('cs-comm-stress', 'teamwork_pressure',
    'During a transient in the simulator, the shift supervisor gives you an order quickly while alarms are sounding. You are not sure you heard the component number. What do you do?',
    'أثناء حالة عابرة في المحاكي، يعطيك مشرف الوردية أمراً بسرعة بينما تدوّي الإنذارات. لست متأكداً من أنك سمعت رقم المكوّن. ماذا تفعل؟',
    [O('Do what you think you heard; there is no time.', 'تنفّذ ما تظن أنك سمعته؛ فلا وقت.', 0, 'A guess under pressure is how wrong components get operated.', 'التخمين تحت الضغط هو كيف تُشغَّل مكوّنات خاطئة.'),
      O('Repeat back the order as you understood it, using the phonetic alphabet, and wait for confirmation.', 'تكرر الأمر كما فهمته مستخدماً الأبجدية الصوتية وتنتظر التأكيد.', 3, 'Closes the loop before acting.', 'يغلق حلقة التواصل قبل التصرف.'),
      O('Ask a colleague what they heard.', 'تسأل زميلاً عمّا سمعه.', 1, 'Adds another uncertain source.', 'يضيف مصدراً آخر غير مؤكد.'),
      O('Wait until the alarms are silenced and then ask.', 'تنتظر حتى تُسكَت الإنذارات ثم تسأل.', 1, 'Delays a needed action.', 'يؤخر إجراءً مطلوباً.')],
    'Three-way communication matters most when it feels slowest. Repeating back the order with the phonetic alphabet costs seconds and catches the errors that pressure creates.',
    'التواصل ثلاثي الاتجاه أهم ما يكون عندما يبدو أبطأ. تكرار الأمر بالأبجدية الصوتية يستغرق ثواني ويكشف الأخطاء التي يولّدها الضغط.'),
  I('cs-comm-stress', 'teamwork_pressure',
    'In an emergency drill, two people are giving you instructions at the same time and they conflict. What do you do?',
    'في تمرين طوارئ، يعطيك شخصان تعليمات في الوقت نفسه وهي متعارضة. ماذا تفعل؟',
    [O('Follow the louder instruction.', 'تتبع التعليمات الأعلى صوتاً.', 0, 'Volume is not authority.', 'علو الصوت ليس صلاحية.'),
      O('State the conflict clearly to both and ask the person in charge which instruction stands.', 'تعلن التعارض بوضوح للاثنين وتسأل المسؤول عن أي التعليمات تُعتمد.', 3, 'Surfaces the conflict to the right authority.', 'يعرض التعارض على صاحب الصلاحية.'),
      O('Do both instructions one after the other.', 'تنفذ التعليمتين واحدة بعد الأخرى.', 0, 'Conflicting actions can make things worse.', 'الإجراءات المتعارضة قد تزيد الأمور سوءاً.'),
      O('Wait until they agree with each other.', 'تنتظر حتى يتفقا.', 1, 'Passive, and they may not realise there is a conflict.', 'موقف سلبي، وقد لا يدركان وجود تعارض.')],
    'Under stress, conflicting instructions are common. The expert response says so out loud and gets a decision from the person in charge, which also tells everyone else what stands.',
    'تحت الضغط تكثر التعليمات المتعارضة. الاستجابة الأفضل تعلن ذلك بصوت مسموع وتحصل على قرار من المسؤول، مما يُعلم الجميع أيضاً بما هو معتمد.'),
  I('cs-comm-stress', 'working_across_cultures',
    'During a tense handover, a colleague whose first language is not yours nods at each point but asks no questions. What do you do?',
    'أثناء تسليم متوتر، يومئ زميل لغته الأولى ليست لغتك عند كل نقطة دون أن يطرح أسئلة. ماذا تفعل؟',
    [O('Take the nods as agreement and finish the handover.', 'تعتبر الإيماءات موافقة وتنهي التسليم.', 0, 'Nodding often means "I am listening", not "I understood".', 'الإيماءة غالباً تعني "أنا أستمع" لا "فهمت".'),
      O('Ask them to say back the key points and actions in their own words.', 'تطلب منه أن يعيد النقاط والإجراءات الرئيسية بكلماته.', 3, 'Checks understanding, not attention.', 'يتحقق من الفهم لا من الانتباه.'),
      O('Speak more slowly and repeat everything.', 'تتحدث ببطء أكبر وتكرر كل شيء.', 1, 'Kind, but still does not confirm understanding.', 'لطيف، لكنه لا يؤكد الفهم بعد.'),
      O('Write the handover down and leave it with them.', 'تكتب التسليم وتتركه معه.', 2, 'Helps, but a written note does not confirm understanding either.', 'مفيد، لكن الملاحظة المكتوبة لا تؤكد الفهم أيضاً.')],
    'Under pressure, and across languages, the only reliable check is a repeat-back in the receiver\'s own words. It is respectful and it catches misunderstandings before they matter.',
    'تحت الضغط ومع اختلاف اللغات، يبقى التحقق الوحيد الموثوق هو أن يعيد المتلقي ما فهمه بكلماته. هذا أسلوب يحترم الآخر ويكشف سوء الفهم قبل أن يصبح مؤثراً.'),

  // ───────────── IO-3 Raising concerns
  I('cs-speak-up', 'raising_concerns',
    'You notice a contractor team starting a job without the pre-job brief their work package requires. They say their supervisor told them to save time. What do you do?',
    'تلاحظ فريق مقاول يبدأ عملاً دون إحاطة ما قبل العمل التي تتطلبها حزمة العمل. يقولون إن مشرفهم طلب منهم توفير الوقت. ماذا تفعل؟',
    [O('Leave it; they are not your team.', 'تتركهم؛ فهم ليسوا فريقك.', 0, 'Safety is everyone\'s, whoever employs the team.', 'السلامة مسؤولية الجميع أياً كان صاحب العمل.'),
      O('Ask them to pause, tell your supervisor straight away, and record it if it happens again.', 'تطلب منهم التوقف مؤقتاً وتبلغ مشرفك فوراً، وتوثّق الأمر إن تكرر.', 3, 'Acts now, escalates through line and records patterns.', 'يتصرف الآن ويصعّد عبر التسلسل ويوثّق الأنماط.'),
      O('Mention it at the next weekly meeting.', 'تذكر ذلك في الاجتماع الأسبوعي القادم.', 1, 'Too late to affect this job.', 'متأخر جداً للتأثير في هذا العمل.'),
      O('Tell their supervisor they are breaking the rules.', 'تبلغ مشرفهم بأنهم يخالفون القواعد.', 2, 'Speaks up, but may not stop the job in time.', 'يتحدث، لكنه قد لا يوقف العمل في الوقت المناسب.')],
    'Raising a concern means acting promptly through the right channel. The best response pauses the work, uses the line, and makes repeat patterns visible. If someone feels unable to use the line, the Employee Concerns Program is there; Kafa\'a never takes concerns itself.',
    'طرح المخاوف يعني التصرف فوراً عبر القناة الصحيحة. الاستجابة الأفضل توقف العمل مؤقتاً وتستخدم التسلسل الإداري وتجعل الأنماط المتكررة مرئية. وإذا شعر أحد بأنه لا يستطيع استخدام التسلسل الإداري فبرنامج مخاوف الموظفين متاح؛ ولا تتلقى كفاءة أي مخاوف بنفسها.'),
  I('cs-speak-up', 'raising_concerns',
    'You raised a quality concern with your manager two weeks ago. Nothing has happened and the issue is still there. What do you do?',
    'طرحت مخاوف تتعلق بالجودة على مديرك قبل أسبوعين. لم يحدث شيء والمشكلة لا تزال قائمة. ماذا تفعل؟',
    [O('Drop it; you have done your part.', 'تتخلى عن الأمر؛ فقد أديت دورك.', 0, 'A concern without follow-up often dies.', 'المخاوف بلا متابعة تموت غالباً.'),
      O('Follow up with your manager, and if it still stalls, use the corrective action programme or the Employee Concerns Program.', 'تتابع مع مديرك، وإن بقي الأمر متعثراً تستخدم برنامج الإجراءات التصحيحية أو برنامج مخاوف الموظفين.', 3, 'Persistent, and uses the formal channels when needed.', 'مثابر، ويستخدم القنوات الرسمية عند الحاجة.'),
      O('Complain about it to colleagues.', 'تشتكي من ذلك لزملائك.', 0, 'Spreads frustration without getting a fix.', 'ينشر الإحباط دون الوصول إلى حل.'),
      O('Go straight to the regulator.', 'تذهب مباشرة إلى الجهة الرقابية.', 1, 'An external option exists, but internal routes come first unless you feel unable to use them.', 'الخيار الخارجي موجود، لكن المسارات الداخلية أولاً ما لم تشعر بعدم القدرة على استخدامها.')],
    'Speaking up includes following up. The best response checks back with the manager, then uses the formal internal channels, which exist so concerns cannot quietly stall. External options remain available.',
    'يشمل التحدث المتابعة أيضاً. الاستجابة الأفضل تعود إلى المدير ثم تستخدم القنوات الداخلية الرسمية التي وُجدت كي لا تتعثر المخاوف بصمت. وتبقى الخيارات الخارجية متاحة.'),
  I('cs-speak-up', 'raising_concerns',
    'A new team member tells you, a team leader, that they think a colleague is taking shortcuts on surveillance tests. They are nervous about it. What do you do?',
    'يخبرك عضو جديد في الفريق، وأنت قائد الفريق، بأنه يعتقد أن زميلاً يختصر خطوات في اختبارات المراقبة. وهو متوتر بشأن ذلك. ماذا تفعل؟',
    [O('Tell them not to worry; the colleague is very experienced.', 'تطمئنه بألّا يقلق؛ فالزميل ذو خبرة كبيرة.', 0, 'Dismisses the concern and the person.', 'يتجاهل المخاوف وصاحبها.'),
      O('Thank them, take the facts, look into it promptly and tell them what you did.', 'تشكره وتأخذ الوقائع وتتحقق من الأمر فوراً وتخبره بما فعلت.', 3, 'Makes speaking up feel safe and worth it.', 'يجعل التحدث آمناً وجديراً بالعناء.'),
      O('Confront the colleague in front of the team.', 'تواجه الزميل أمام الفريق.', 0, 'Exposes the reporter and humiliates the colleague.', 'يكشف المُبلِّغ ويحرج الزميل.'),
      O('Note it and watch the colleague over the next month.', 'تدوّن الأمر وتراقب الزميل خلال الشهر القادم.', 1, 'Too slow for a possible test integrity issue.', 'بطيء جداً لمشكلة محتملة في سلامة الاختبار.')],
    'How a leader responds decides whether people speak up again. Thanking, acting promptly and closing the loop builds a safety-conscious work environment; dismissing or exposing the reporter destroys it.',
    'طريقة استجابة القائد تحدد ما إذا كان الناس سيتحدثون مرة أخرى. الشكر والتصرف الفوري وإغلاق الحلقة يبني بيئة عمل واعية بالسلامة؛ أما التجاهل أو كشف المُبلِّغ فيهدمها.'),

  // ───────────── IO-4 Working across cultures
  I('cs-cross-cultural', 'working_across_cultures',
    'You are working with engineers from a partner company who prefer to settle decisions in a meeting with their manager present. Your team prefers quick decisions by message. A decision is needed this week. What do you do?',
    'تعمل مع مهندسين من شركة شريكة يفضّلون حسم القرارات في اجتماع بحضور مديرهم، بينما يفضّل فريقك القرارات السريعة عبر الرسائل. يلزم اتخاذ قرار هذا الأسبوع. ماذا تفعل؟',
    [O('Send the decision by message and ask for a reply by tomorrow.', 'ترسل القرار برسالة وتطلب رداً بحلول الغد.', 1, 'Fast, but ignores how the partner decides.', 'سريع، لكنه يتجاهل طريقة الشريك في اتخاذ القرار.'),
      O('Set up a short meeting with their manager, share the facts beforehand and confirm the decision in writing afterwards.', 'ترتب اجتماعاً قصيراً بحضور مديرهم، وتشارك الوقائع مسبقاً، وتؤكد القرار كتابةً بعده.', 3, 'Works with their way and keeps a clear record.', 'يعمل وفق أسلوبهم ويحتفظ بسجل واضح.'),
      O('Wait until they raise it.', 'تنتظر حتى يطرحوا الموضوع.', 0, 'The decision may be missed.', 'قد يفوت القرار.'),
      O('Ask your manager to decide for both teams.', 'تطلب من مديرك أن يقرر عن الفريقين.', 1, 'Avoids the cross-team work rather than doing it.', 'يتجنب العمل بين الفريقين بدلاً من القيام به.')],
    'Working across cultures means adapting the process so that real agreement happens, then making it explicit. A meeting in their preferred format, with facts shared in advance and a written confirmation, gets a decision both sides own.',
    'العمل عبر الثقافات يعني تكييف الإجراء كي يتحقق اتفاق حقيقي ثم توضيحه. اجتماع بالشكل المفضّل لديهم، مع مشاركة الوقائع مسبقاً وتأكيد كتابي، يُنتج قراراً يتبنّاه الطرفان.'),
  I('cs-cross-cultural', 'working_across_cultures',
    'In a mixed team, you notice that the newer UAE engineers rarely speak in technical reviews led by the most senior expatriate experts. What do you do as the review lead?',
    'في فريق مختلط، تلاحظ أن المهندسين الإماراتيين الأحدث نادراً ما يتحدثون في المراجعات الفنية التي يقودها أقدم الخبراء الوافدين. ماذا تفعل بصفتك قائد المراجعة؟',
    [O('Nothing; they will speak when they are ready.', 'لا شيء؛ سيتحدثون عندما يكونون مستعدين.', 0, 'Their knowledge and questions stay unused.', 'تبقى معرفتهم وأسئلتهم غير مستثمرة.'),
      O('Give each person a part of the review to present and invite questions from everyone by name.', 'تكلّف كل شخص بجزء من المراجعة ليعرضه وتدعو الجميع بالاسم لطرح الأسئلة.', 3, 'Structures participation so knowledge flows both ways.', 'ينظّم المشاركة كي تنتقل المعرفة في الاتجاهين.'),
      O('Tell the senior experts to talk less.', 'تطلب من الخبراء الأقدم أن يتحدثوا أقل.', 1, 'Blunt, and does not build the newer engineers\' voice.', 'أسلوب فظ، ولا يبني صوت المهندسين الأحدث.'),
      O('Hold a separate meeting just for the newer engineers.', 'تعقد اجتماعاً منفصلاً للمهندسين الأحدث فقط.', 2, 'Helps confidence, but keeps the groups apart.', 'يعزز الثقة، لكنه يُبقي المجموعتين منفصلتين.')],
    'Knowledge transfer only works in both directions when everyone takes part. Structuring the review so each person presents and is asked for questions builds confidence and makes the mixed team stronger.',
    'لا ينجح نقل المعرفة في الاتجاهين إلا عندما يشارك الجميع. تنظيم المراجعة بحيث يعرض كل شخص ويُطلب منه طرح الأسئلة يبني الثقة ويجعل الفريق المختلط أقوى.'),
  I('cs-cross-cultural', 'working_across_cultures',
    'A colleague from another country makes a joke about a group that some team members find offensive. Nobody says anything. What do you do?',
    'يلقي زميل من بلد آخر نكتة عن فئة ما يجدها بعض أعضاء الفريق مسيئة. لا أحد يقول شيئاً. ماذا تفعل؟',
    [O('Laugh along to keep the mood light.', 'تضحك مجاراةً للحفاظ على أجواء لطيفة.', 0, 'Signals that it is acceptable.', 'يوحي بأن الأمر مقبول.'),
      O('Speak to the colleague privately and explain why it landed badly.', 'تتحدث مع الزميل على انفراد وتشرح لماذا كان وقعها سيئاً.', 3, 'Respectful, direct and likely to change behaviour.', 'محترم ومباشر ومن المرجح أن يغيّر السلوك.'),
      O('Report it to HR immediately.', 'تبلغ الموارد البشرية فوراً.', 2, 'May be needed if it continues, but a conversation often works first.', 'قد يكون لازماً إن تكرر، لكن الحوار ينجح أولاً في الغالب.'),
      O('Ignore it; it was only a joke.', 'تتجاهلها؛ فقد كانت مجرد نكتة.', 0, 'Leaves colleagues feeling unsafe.', 'يترك الزملاء يشعرون بعدم الأمان.')],
    'A respectful work environment is a safety-culture trait: people who feel disrespected speak up less. A private, direct conversation usually fixes it; escalate if it continues.',
    'بيئة العمل القائمة على الاحترام سمة من سمات ثقافة السلامة: فمن يشعر بعدم الاحترام يتحدث أقل. الحوار المباشر على انفراد يحل الأمر عادة؛ وصعّد إن تكرر.'),

  // ───────────── IO-5 Developing others
  I('cs-developing', 'learning_change',
    'A new operator in your crew made a minor error on a routine task. It caused no harm. What is the best way to respond?',
    'ارتكب مشغّل جديد في طاقمك خطأً بسيطاً في مهمة روتينية لم يسبب أي ضرر. ما أفضل طريقة للاستجابة؟',
    [O('Fix it yourself quietly so they are not embarrassed.', 'تصلحه بنفسك بهدوء كي لا يُحرَج.', 1, 'Kind, but they learn nothing and errors go unreported.', 'لطيف، لكنه لا يتعلّم شيئاً ولا يُبلَّغ عن الأخطاء.'),
      O('Talk it through with them soon after: what happened, why, and what they will do next time.', 'تناقش الأمر معه بعد وقت قصير: ماذا حدث ولماذا وماذا سيفعل في المرة القادمة.', 3, 'Timely, specific coaching that builds the habit.', 'توجيه في وقته ومحدد يبني العادة.'),
      O('Tell the shift manager so it is on record.', 'تبلغ مدير الوردية كي يُسجَّل.', 2, 'Recording matters, but the coaching conversation is missing.', 'التسجيل مهم، لكن حوار التوجيه غائب.'),
      O('Point it out in front of the crew as a lesson for all.', 'تشير إليه أمام الطاقم درساً للجميع.', 0, 'Public blame discourages reporting.', 'اللوم العلني يثبّط الإبلاغ.')],
    'Developing others means timely, specific, private feedback that helps the person do better next time, while still using the formal reporting routes for anything that needs them.',
    'تطوير الآخرين يعني تغذية راجعة في وقتها ومحددة وعلى انفراد تساعد الشخص على الأداء الأفضل في المرة القادمة، مع الاستمرار في استخدام مسارات الإبلاغ الرسمية لكل ما يحتاجها.'),
  I('cs-developing', 'learning_change',
    'You are the only person in your team who knows how to carry out a rare calibration. It is needed about twice a year. What do you do?',
    'أنت الوحيد في فريقك الذي يعرف كيف يجري معايرة نادرة لا تُطلب إلا مرتين تقريباً في السنة. ماذا تفعل؟',
    [O('Keep doing it yourself; it is quicker.', 'تواصل إجراءها بنفسك؛ فذلك أسرع.', 0, 'Leaves a single point of knowledge.', 'يُبقي المعرفة محصورة في شخص واحد.'),
      O('Agree with your manager to have a colleague shadow and then perform it under your supervision, and update the guidance.', 'تتفق مع مديرك على أن يرافقك زميل ثم يجريها تحت إشرافك، وتحدّث الإرشادات.', 3, 'Transfers the know-how and makes it durable.', 'ينقل الخبرة ويجعلها مستدامة.'),
      O('Write notes and put them in a shared folder.', 'تكتب ملاحظات وتضعها في مجلد مشترك.', 2, 'Useful, but notes alone rarely transfer practical skill.', 'مفيد، لكن الملاحظات وحدها نادراً ما تنقل المهارة العملية.'),
      O('Tell your manager it is a risk.', 'تخبر مديرك أن ذلك يمثل خطراً.', 1, 'Names the risk but does not reduce it.', 'يسمّي الخطر لكنه لا يقلّله.')],
    'Knowledge that sits with one person is a risk to the plant. The best response transfers it by doing: shadowing, supervised practice and updated guidance.',
    'المعرفة المحصورة في شخص واحد خطر على المحطة. الاستجابة الأفضل تنقلها بالممارسة: المرافقة والتمرين تحت الإشراف وتحديث الإرشادات.'),
  I('cs-developing', 'digital_judgement',
    'A colleague you mentor shows you a report they drafted with an approved AI assistant. It reads well but contains two figures that do not match the source data. How do you coach them?',
    'يُريك زميل تتولى إرشاده تقريراً صاغه بمساعد ذكاء اصطناعي معتمد. يبدو جيداً لكنه يتضمن رقمين لا يطابقان بيانات المصدر. كيف توجّهه؟',
    [O('Correct the two figures yourself and send it.', 'تصحح الرقمين بنفسك وترسله.', 1, 'Fixes the report, not the habit.', 'يصلح التقرير لا العادة.'),
      O('Ask them how they checked the figures, show the mismatch and agree a simple check for next time.', 'تسأله كيف تحقق من الأرقام، وتُريه عدم التطابق، وتتفقان على تحقق بسيط للمرة القادمة.', 3, 'Builds their own verification habit.', 'يبني لديه عادة التحقق بنفسه.'),
      O('Tell them to stop using AI for reports.', 'تطلب منه التوقف عن استخدام الذكاء الاصطناعي في التقارير.', 0, 'Bans the tool instead of teaching its safe use.', 'يمنع الأداة بدلاً من تعليم استخدامها الآمن.'),
      O('Praise the writing and mention the figures briefly.', 'تثني على الصياغة وتذكر الأرقام باختصار.', 1, 'The key lesson gets lost.', 'يضيع الدرس الأساسي.')],
    'Coaching on AI-assisted work is about the verification habit: ask, show and agree a check, so the person catches it themselves next time. Banning the tool or silently fixing the output teaches nothing.',
    'التوجيه في العمل بمساعدة الذكاء الاصطناعي يتمحور حول عادة التحقق: اسأل وأرِه واتفقا على طريقة للتحقق، كي يكتشف الخطأ بنفسه في المرة القادمة. منع الأداة أو إصلاح المخرجات بصمت لا يعلّم شيئاً.'),

  // ───────────── SR-1 Learning agility
  I('cs-learning-agility', 'learning_change',
    'Your team is moving from paper log sheets to a digital rounds tool next month. You have not used it before. What do you do?',
    'سينتقل فريقك من سجلات الجولات الورقية إلى أداة رقمية للجولات الشهر القادم. لم تستخدمها من قبل. ماذا تفعل؟',
    [O('Wait for the training to be scheduled.', 'تنتظر حتى تُجدوَل الدورة التدريبية.', 1, 'Passive, and you start behind.', 'موقف سلبي، وتبدأ متأخراً.'),
      O('Take the available training early, try the tool in the practice mode and note questions for the rollout.', 'تأخذ التدريب المتاح مبكراً، وتجرب الأداة في وضع التمرين، وتدوّن أسئلتك لمرحلة الإطلاق.', 3, 'Learns ahead and feeds the change.', 'يتعلّم مسبقاً ويسهم في نجاح التغيير.'),
      O('Keep using paper until someone insists.', 'تواصل استخدام الورق حتى يصرّ أحد.', 0, 'Resists the change and creates two systems.', 'يقاوم التغيير ويخلق نظامين متوازيين.'),
      O('Ask a colleague who has used it to show you once.', 'تطلب من زميل استخدمها أن يريك مرة واحدة.', 2, 'Good, but one demonstration is not practice.', 'جيد، لكن عرضاً واحداً ليس تمريناً.')],
    'Learning agility is getting ahead of change: learning early, practising safely and bringing questions back so the rollout improves.',
    'سرعة التعلّم تعني استباق التغيير: التعلّم مبكراً والتمرّن بأمان وإعادة الأسئلة كي يتحسن الإطلاق.'),
  I('cs-learning-agility', 'learning_change',
    'In your check-in, your manager gives you feedback you disagree with about how you handle shift turnover. What do you do?',
    'في التقييم الدوري، يقدّم لك مديرك تغذية راجعة لا توافق عليها بشأن طريقة تعاملك مع تسليم الوردية. ماذا تفعل؟',
    [O('Argue the point until they change the feedback.', 'تجادل حتى يغيّر تغذيته الراجعة.', 0, 'Defends instead of learning.', 'يدافع بدلاً من أن يتعلّم.'),
      O('Ask for specific examples, consider them, and agree one thing to try at the next turnovers.', 'تطلب أمثلة محددة وتتأملها وتتفق على أمر واحد تجربه في عمليات التسليم القادمة.', 3, 'Turns feedback into an experiment.', 'يحوّل التغذية الراجعة إلى تجربة.'),
      O('Accept it politely and change nothing.', 'تقبلها بأدب ولا تغيّر شيئاً.', 0, 'No learning happens.', 'لا يحدث أي تعلّم.'),
      O('Ask a peer whether they agree with the feedback.', 'تسأل زميلاً إن كان يتفق مع التغذية الراجعة.', 2, 'A second view helps, but the next step is still missing.', 'الرأي الثاني مفيد، لكن الخطوة التالية لا تزال غائبة.')],
    'Learning agility includes learning from feedback you did not expect. Asking for specifics and agreeing a small experiment keeps learning going even when you are not sure the feedback is right.',
    'تشمل سرعة التعلّم التعلّم من تغذية راجعة لم تتوقعها. طلب التفاصيل والاتفاق على تجربة صغيرة يُبقي التعلّم مستمراً حتى عندما لا تكون متأكداً من صحة التغذية الراجعة.'),
  I('cs-learning-agility', 'learning_change',
    'An operating experience report from another plant describes an event in a system similar to one you work on. What do you do with it?',
    'يصف تقرير خبرة تشغيلية من محطة أخرى حدثاً في نظام مشابه لنظام تعمل عليه. ماذا تفعل به؟',
    [O('Read it and file it.', 'تقرأه وتحفظه.', 1, 'Information, not learning.', 'معلومة، لا تعلّم.'),
      O('Compare it with your own system and procedures, and raise anything that could apply here.', 'تقارنه بنظامك وإجراءاتك وتطرح أي أمر قد ينطبق هنا.', 3, 'Applies the lesson locally.', 'يطبّق الدرس محلياً.'),
      O('Assume it does not apply; their plant is different.', 'تفترض أنه لا ينطبق؛ فمحطتهم مختلفة.', 0, '"It cannot happen here" is a known trap.', '"لا يمكن أن يحدث هنا" فخ معروف.'),
      O('Share it with your crew at the next brief.', 'تشاركه مع طاقمك في الإحاطة القادمة.', 2, 'Spreads awareness, but does not check applicability.', 'ينشر الوعي لكنه لا يتحقق من قابلية التطبيق.')],
    'Operating experience only helps if someone asks "could this happen here?" and checks. The expert response compares the event with local systems and procedures and raises what applies.',
    'لا تفيد الخبرة التشغيلية إلا إذا سأل أحدهم "هل يمكن أن يحدث هذا هنا؟" وتحقق. الاستجابة الأفضل تقارن الحدث بالأنظمة والإجراءات المحلية وتطرح ما ينطبق.'),

  // ───────────── SR-2 Resilience and self-management
  I('cs-resilience', 'teamwork_pressure',
    'It is the last hours of a long night shift during an outage. You notice you are re-reading steps and losing your place. A critical task is next. What do you do?',
    'إنها الساعات الأخيرة من وردية ليلية طويلة أثناء الانقطاع. تلاحظ أنك تعيد قراءة الخطوات وتفقد موضعك. المهمة التالية حرجة. ماذا تفعل؟',
    [O('Push through; it is nearly the end of the shift.', 'تواصل؛ فالوردية أوشكت على الانتهاء.', 0, 'Fatigue errors cluster at exactly this point.', 'أخطاء الإرهاق تتركز في هذه النقطة بالذات.'),
      O('Tell your supervisor you are not fit for the critical task now and agree who does it or when.', 'تخبر مشرفك بأنك لست مؤهلاً للمهمة الحرجة الآن وتتفقان على من ينفذها أو متى.', 3, 'Recognises the limit and uses the fitness-for-duty route.', 'يدرك الحد ويستخدم مسار الأهلية للعمل.'),
      O('Drink coffee and slow down.', 'تشرب القهوة وتبطئ.', 1, 'Helps a little, but does not remove the risk.', 'يساعد قليلاً لكنه لا يزيل الخطر.'),
      O('Ask a colleague to peer-check every step.', 'تطلب من زميل التحقق من كل خطوة.', 2, 'Adds a barrier, but the supervisor should know.', 'يضيف خط دفاع، لكن يجب أن يعلم المشرف.')],
    'Self-management means noticing your own limits and acting on them before they show up as errors. Telling the supervisor and re-planning the critical task is a strength, not a weakness. Kafa\'a never records health information; this is about the behaviour.',
    'إدارة الذات تعني ملاحظة حدودك والتصرف بناءً عليها قبل أن تظهر في صورة أخطاء. إخبار المشرف وإعادة تخطيط المهمة الحرجة قوة لا ضعف. ولا تسجّل كفاءة أي معلومات صحية؛ فالأمر يتعلق بالسلوك.'),
  I('cs-resilience', 'learning_change',
    'A job you led had to be redone because of an error in your planning. You feel embarrassed. What is the most useful response?',
    'اضطُر إلى إعادة عمل قدته بسبب خطأ في تخطيطك. تشعر بالحرج. ما الاستجابة الأكثر فائدة؟',
    [O('Keep a low profile until people forget.', 'تبتعد عن الأضواء حتى ينسى الناس.', 0, 'Avoidance blocks learning.', 'التجنب يعيق التعلّم.'),
      O('Own it in the post-job review, identify what you will change, and move on to the next job.', 'تتحمّل المسؤولية في مراجعة ما بعد العمل وتحدد ما ستغيّره ثم تنتقل إلى العمل التالي.', 3, 'Recovers by learning, not by dwelling.', 'يتعافى بالتعلّم لا بالاجترار.'),
      O('Explain that the schedule pressure caused it.', 'توضح أن ضغط الجدول هو السبب.', 1, 'May be partly true, but shifts ownership.', 'قد يكون صحيحاً جزئياً، لكنه ينقل المسؤولية.'),
      O('Go over the error again and again in your head.', 'تعيد التفكير في الخطأ مراراً.', 1, 'Rumination drains energy for the next job.', 'الاجترار يستنزف الطاقة اللازمة للعمل التالي.')],
    'Resilience is recovering well: owning the error, extracting the lesson and returning focused. That serves both the person and the plant.',
    'المرونة هي التعافي الجيد: تحمّل مسؤولية الخطأ واستخلاص الدرس والعودة بتركيز. وهذا يخدم الشخص والمحطة معاً.'),
  I('cs-resilience', 'teamwork_pressure',
    'Your outage team has worked long hours for three weeks and tempers are short. You are the team leader. What do you do?',
    'عمل فريقك ساعات طويلة لثلاثة أسابيع أثناء الانقطاع، والأعصاب مشدودة. أنت قائد الفريق. ماذا تفعل؟',
    [O('Push harder; there is only a week left.', 'تضغط أكثر؛ فلم يبق سوى أسبوع.', 0, 'Raises error risk at the end of the outage.', 'يرفع خطر الأخطاء في نهاية الانقطاع.'),
      O('Check the hours against the fatigue rules, rebalance the work and brief the team on watching for fatigue.', 'تراجع الساعات مقابل قواعد الإرهاق، وتعيد توزيع العمل، وتحيط الفريق بضرورة الانتباه لعلامات الإرهاق.', 3, 'Protects alertness with concrete actions.', 'يحمي اليقظة بإجراءات ملموسة.'),
      O('Organise a team dinner.', 'تنظم عشاءً للفريق.', 1, 'Kind, but does not address the workload.', 'لفتة لطيفة، لكنها لا تعالج عبء العمل.'),
      O('Tell people to speak up if they feel tired.', 'تطلب من الناس الإفصاح إن شعروا بالتعب.', 2, 'Right message, but the leader should act too.', 'رسالة صحيحة، لكن على القائد أن يتصرف أيضاً.')],
    'Leaders build team resilience through workload and routines, not slogans. Checking hours, rebalancing work and briefing on fatigue protects people and the plant in the riskiest last week.',
    'يبني القادة مرونة الفريق عبر عبء العمل والروتين لا عبر الشعارات. مراجعة الساعات وإعادة توزيع العمل والإحاطة بالإرهاق تحمي الأفراد والمحطة في الأسبوع الأخير الأكثر خطورة.'),

  // ───────────── SR-3 Adaptability
  I('cs-adaptability', 'conservative_decisions',
    'A spare part for your outage job arrives two days late. The original sequence no longer works. What do you do?',
    'وصلت قطعة غيار لعملك في الانقطاع متأخرة يومين. لم يعد الترتيب الأصلي صالحاً. ماذا تفعل؟',
    [O('Keep to the original sequence and work longer hours later.', 'تلتزم بالترتيب الأصلي وتعمل ساعات أطول لاحقاً.', 0, 'Forces the old plan and adds fatigue risk.', 'يفرض الخطة القديمة ويضيف خطر الإرهاق.'),
      O('Re-sequence with work control, check the new risks and re-brief the crew.', 'تعيد الترتيب مع التحكم في العمل، وتتحقق من المخاطر الجديدة، وتعيد إحاطة الطاقم.', 3, 'Adapts the plan and the risk picture together.', 'يكيّف الخطة وصورة المخاطر معاً.'),
      O('Start the next job in the package while you wait.', 'تبدأ العمل التالي في الحزمة أثناء الانتظار.', 1, 'Adapts, but informally and without a re-brief.', 'يتكيّف لكن بشكل غير رسمي ودون إعادة إحاطة.'),
      O('Report the delay and wait for instructions.', 'تبلغ عن التأخير وتنتظر التعليمات.', 2, 'Safe, but leaves the re-planning to others.', 'آمن، لكنه يترك إعادة التخطيط للآخرين.')],
    'Adaptability is re-planning safely when conditions change: the sequence, the risks and the crew\'s understanding all move together. Forcing the old plan or improvising informally both carry hidden risk.',
    'التكيّف هو إعادة التخطيط بأمان عند تغيّر الظروف: الترتيب والمخاطر وفهم الطاقم تتغيّر معاً. فرض الخطة القديمة أو الارتجال غير الرسمي يحملان مخاطر خفية.'),
  I('cs-adaptability', 'learning_change',
    'Your role is changing: part of your monitoring work will be done by a new digital system next year, and you will spend more time on analysis. How do you respond?',
    'دورك يتغيّر: سيتولى نظام رقمي جديد جزءاً من أعمال المراقبة العام القادم، وستقضي وقتاً أطول في التحليل. كيف تستجيب؟',
    [O('Wait and see what the new role looks like.', 'تنتظر لترى كيف سيبدو الدور الجديد.', 1, 'Leaves your development to chance.', 'يترك تطورك للصدفة.'),
      O('Look at the future role profile, agree a learning plan with your manager and start on the analysis skills now.', 'تطّلع على ملف الدور المستقبلي، وتتفق مع مديرك على خطة تعلّم، وتبدأ اكتساب مهارات التحليل الآن.', 3, 'Moves early toward the new role.', 'يتحرك مبكراً نحو الدور الجديد.'),
      O('Argue that the monitoring work should stay manual.', 'تجادل بأن أعمال المراقبة يجب أن تبقى يدوية.', 0, 'Resists rather than adapts.', 'يقاوم بدلاً من أن يتكيّف.'),
      O('Look for a different role that will not change.', 'تبحث عن دور آخر لن يتغيّر.', 1, 'Few roles will not change.', 'قليلة هي الأدوار التي لن تتغيّر.')],
    'Adaptable people treat role change as a plan, not a threat: they read the future profile, agree a learning plan and start early.',
    'الأشخاص القادرون على التكيّف يتعاملون مع تغيّر الدور بوصفه خطة لا تهديداً: يقرأون الملف المستقبلي، ويتفقون على خطة تعلّم، ويبدأون مبكراً.'),
  I('cs-adaptability', 'teamwork_pressure',
    'Halfway through a shift, you are moved to support a different team on an unfamiliar system. What do you do first?',
    'في منتصف الوردية، تُنقل لدعم فريق آخر على نظام غير مألوف لك. ماذا تفعل أولاً؟',
    [O('Start helping straight away; they need hands.', 'تبدأ المساعدة فوراً؛ فهم بحاجة إلى أيدٍ.', 0, 'Unfamiliar work without a brief is a known error trap.', 'العمل غير المألوف دون إحاطة فخ معروف للأخطاء.'),
      O('Get a short brief on the system, the task and the hazards, and say what you have and have not done before.', 'تحصل على إحاطة قصيرة عن النظام والمهمة والمخاطر، وتوضح ما سبق لك فعله وما لم يسبق.', 3, 'Adapts quickly while being honest about limits.', 'يتكيّف بسرعة مع الصراحة بشأن حدوده.'),
      O('Ask to stay with your own team.', 'تطلب البقاء مع فريقك.', 0, 'Avoids the change.', 'يتجنب التغيير.'),
      O('Watch the team for an hour before doing anything.', 'تراقب الفريق ساعة قبل أن تفعل أي شيء.', 1, 'Cautious, but slow and still without a brief.', 'حذر، لكنه بطيء ولا يزال دون إحاطة.')],
    'Adapting to a new team means getting up to speed fast and safely: a brief on the task and hazards, and honesty about what you have not done before.',
    'التكيّف مع فريق جديد يعني اللحاق بالركب بسرعة وأمان: إحاطة بالمهمة والمخاطر، وصراحة بشأن ما لم يسبق لك فعله.'),

  // ───────────── SR-4 Digital and AI judgement
  I('cs-digital-judgement', 'digital_judgement',
    'An anomaly-detection tool flags a pump as likely to fail within a week. Your own checks of vibration and temperature look normal. What do you do?',
    'تشير أداة لرصد الحالات الشاذة إلى أن مضخة يُرجّح أن تتعطل خلال أسبوع. فحوصك الخاصة للاهتزاز والحرارة تبدو طبيعية. ماذا تفعل؟',
    [O('Ignore the tool; your checks are normal.', 'تتجاهل الأداة؛ ففحوصك طبيعية.', 1, 'The tool may see a pattern you do not.', 'قد ترى الأداة نمطاً لا تراه.'),
      O('Raise it for an engineering review with both the tool output and your readings, and agree extra monitoring.', 'تطرحه لمراجعة هندسية مع مخرجات الأداة وقراءاتك، وتتفقون على مراقبة إضافية.', 3, 'Treats the tool as a signal to check, not a verdict.', 'يعامل الأداة إشارةً للتحقق لا حكماً نهائياً.'),
      O('Take the pump out of service on the tool\'s word.', 'تخرج المضخة من الخدمة بناءً على كلام الأداة.', 0, 'Acts on an unverified output.', 'يتصرف بناءً على مخرجات غير متحقق منها.'),
      O('Check the readings again tomorrow.', 'تعيد فحص القراءات غداً.', 2, 'Sensible, but the conflict should be shared now.', 'منطقي، لكن ينبغي مشاركة التعارض الآن.')],
    'AI tools are inputs to human judgement. When a tool and independent indications disagree, the expert response puts both in front of the right reviewers and adds monitoring, rather than trusting or dismissing either.',
    'أدوات الذكاء الاصطناعي مدخلات للحكم البشري. عندما تختلف الأداة مع المؤشرات المستقلة، تضع الاستجابة الأفضل الاثنين أمام المراجعين المناسبين وتضيف مراقبة، بدلاً من الوثوق بأحدهما أو رفضه.'),
  I('cs-digital-judgement', 'digital_judgement',
    'You want help drafting an email about a delayed work order. The fastest tool is a public chatbot on your phone. What do you do?',
    'تريد مساعدة في صياغة بريد إلكتروني عن أمر عمل متأخر. أسرع أداة هي روبوت محادثة عام على هاتفك. ماذا تفعل؟',
    [O('Use the public chatbot but remove the work order number.', 'تستخدم الروبوت العام لكن تحذف رقم أمر العمل.', 1, 'Still sends internal information to an unapproved tool.', 'لا يزال يرسل معلومات داخلية إلى أداة غير معتمدة.'),
      O('Use the approved assistant, or write it yourself.', 'تستخدم المساعد المعتمد أو تكتبه بنفسك.', 3, 'Keeps internal information in approved tools.', 'يُبقي المعلومات الداخلية في الأدوات المعتمدة.'),
      O('Use the public chatbot; it is only an email.', 'تستخدم الروبوت العام؛ فهو مجرد بريد.', 0, 'Internal plant information leaves the company.', 'تخرج معلومات المحطة الداخلية من الشركة.'),
      O('Ask IT whether the public chatbot is allowed.', 'تسأل تقنية المعلومات إن كان الروبوت العام مسموحاً.', 2, 'Reasonable, but the approved-tool rule already answers it.', 'معقول، لكن قاعدة الأدوات المعتمدة تجيب عن ذلك أصلاً.')],
    'Digital judgement includes knowing which tools may see which information. Internal work information goes only into approved tools, however quick the alternative.',
    'يشمل الحكم الرقمي معرفة الأدوات التي يجوز لها الاطلاع على كل نوع من المعلومات. معلومات العمل الداخلية لا تُدخَل إلا في الأدوات المعتمدة، مهما كان البديل سريعاً.'),
  I('cs-digital-judgement', 'conservative_decisions',
    'A digital twin model predicts that you can delay a planned inspection by six months. The model has not been validated for the current operating mode. What do you recommend?',
    'يتوقع نموذج التوأم الرقمي أن بالإمكان تأجيل فحص مخطط له ستة أشهر. لم يُتحقق من صحة النموذج لنمط التشغيل الحالي. بماذا توصي؟',
    [O('Delay the inspection; the model says it is fine.', 'تأجيل الفحص؛ فالنموذج يقول إن الأمر على ما يرام.', 0, 'Relies on a model outside its validated range.', 'يعتمد على نموذج خارج نطاق التحقق من صحته.'),
      O('Keep the inspection on schedule and ask for the model to be validated for this mode before using it for such decisions.', 'إبقاء الفحص في موعده وطلب التحقق من صحة النموذج لهذا النمط قبل استخدامه في مثل هذه القرارات.', 3, 'Conservative, and fixes the gap for the future.', 'محافظ، ويعالج الفجوة للمستقبل.'),
      O('Delay by three months as a compromise.', 'التأجيل ثلاثة أشهر حلاً وسطاً.', 0, 'Still relies on the unvalidated model.', 'لا يزال يعتمد على النموذج غير المتحقق منه.'),
      O('Ask the vendor whether the model can be trusted.', 'تسأل المورّد إن كان يمكن الوثوق بالنموذج.', 1, 'Useful input, but not a validation.', 'مدخل مفيد لكنه ليس تحققاً.')],
    'A model is only as good as the range it was validated for. Outside that range, the conservative choice keeps the established schedule while the model is validated.',
    'لا يكون النموذج جيداً إلا ضمن النطاق الذي تم التحقق من صحته فيه. خارج هذا النطاق، يبقي الخيار المحافظ على الجدول المعتمد ريثما يُتحقق من النموذج.'),

  // ───────────── SR-5 Personal accountability
  I('cs-accountability', 'procedure_use',
    'After finishing a job, you realise you left a valve in the wrong position. Nobody has noticed and nothing has happened. What do you do?',
    'بعد إنهاء عمل ما، تدرك أنك تركت صماماً في وضع خاطئ. لم يلاحظ أحد ولم يحدث شيء. ماذا تفعل؟',
    [O('Quietly put it right and say nothing.', 'تصححه بهدوء ولا تقول شيئاً.', 0, 'An unauthorised manipulation that also hides the lesson.', 'تغيير غير مصرّح به ويخفي الدرس أيضاً.'),
      O('Tell the control room straight away so they can decide how to restore it, and report it.', 'تبلغ غرفة التحكم فوراً كي تقرر طريقة إعادته، وتبلغ عن الأمر.', 3, 'Owns the error and lets the plant respond correctly.', 'يتحمّل مسؤولية الخطأ ويتيح للمحطة الاستجابة الصحيحة.'),
      O('Tell your supervisor at the end of the shift.', 'تخبر مشرفك في نهاية الوردية.', 1, 'Honest, but the plant is in the wrong state until then.', 'صادق، لكن المحطة تبقى في حالة خاطئة حتى ذلك الحين.'),
      O('Mention it at the next post-job review.', 'تذكره في مراجعة ما بعد العمل القادمة.', 0, 'Far too late for a configuration error.', 'متأخر جداً لخطأ في وضع المحطة.')],
    'Personal accountability means owning errors immediately, especially when nobody would notice. The control room must know the real plant state and decide how to restore it.',
    'المساءلة الشخصية تعني تحمّل مسؤولية الأخطاء فوراً، خاصة حين لا يلاحظها أحد. يجب أن تعرف غرفة التحكم الحالة الحقيقية للمحطة وتقرر طريقة إعادتها.'),
  I('cs-accountability', 'teamwork_pressure',
    'You promised another team a test result by Thursday, but an urgent job means you cannot deliver. What do you do?',
    'وعدت فريقاً آخر بنتيجة اختبار بحلول الخميس، لكن عملاً عاجلاً يعني أنك لن تستطيع التسليم. ماذا تفعل؟',
    [O('Say nothing and deliver when you can.', 'لا تقول شيئاً وتسلّم حين تستطيع.', 0, 'The other team plans on a promise that will not be kept.', 'يخطط الفريق الآخر بناءً على وعد لن يُوفى به.'),
      O('Tell them now, give a realistic new date and ask whether the delay affects their work.', 'تبلغهم الآن، وتعطي موعداً جديداً واقعياً، وتسأل إن كان التأخير يؤثر على عملهم.', 3, 'Owns the commitment and its consequences.', 'يتحمّل مسؤولية الالتزام وعواقبه.'),
      O('Ask a colleague to do the test in a hurry.', 'تطلب من زميل إجراء الاختبار على عجل.', 1, 'Shifts the problem and may reduce quality.', 'ينقل المشكلة وقد يقلل الجودة.'),
      O('Tell them on Thursday.', 'تبلغهم يوم الخميس.', 1, 'Honest, but too late for them to re-plan.', 'صادق، لكنه متأخر جداً لإعادة تخطيطهم.')],
    'Accountability covers commitments as well as errors. Telling people early, with a realistic date and a question about the impact, lets them re-plan.',
    'تشمل المساءلة الالتزامات كما تشمل الأخطاء. إبلاغ الآخرين مبكراً بموعد واقعي وسؤال عن الأثر يتيح لهم إعادة التخطيط.'),
  I('cs-accountability', 'learning_change',
    'In a post-job review, the team is listing what went wrong. One problem started with a decision you made. What do you do?',
    'في مراجعة ما بعد العمل، يسرد الفريق ما لم يسر على ما يرام. إحدى المشكلات بدأت بقرار اتخذته أنت. ماذا تفعل؟',
    [O('Stay quiet unless someone asks.', 'تلتزم الصمت ما لم يسألك أحد.', 0, 'The team learns less.', 'يتعلّم الفريق أقل.'),
      O('Say that it started with your decision, explain your reasoning at the time and what you would do differently.', 'تقول إنها بدأت بقرارك، وتشرح تفكيرك آنذاك وما الذي كنت ستفعله بشكل مختلف.', 3, 'Models blame-free ownership that helps everyone learn.', 'يجسّد تحمّل المسؤولية دون لوم بما يساعد الجميع على التعلّم.'),
      O('Point out the other factors that contributed.', 'تشير إلى العوامل الأخرى التي أسهمت في المشكلة.', 1, 'Relevant, but sounds like deflection on its own.', 'ذو صلة، لكنه يبدو تهرباً إذا جاء وحده.'),
      O('Apologise and promise it will not happen again.', 'تعتذر وتعد بألّا يتكرر ذلك.', 2, 'Owns it, but without the reasoning the team can learn from.', 'يتحمّل المسؤولية لكن دون التفكير الذي يمكن للفريق التعلّم منه.')],
    'Owning your part openly, with the reasoning behind it, is what makes post-job reviews useful. It also makes it easier for others to do the same.',
    'تحمّل نصيبك من المسؤولية علناً مع شرح التفكير وراءه هو ما يجعل مراجعات ما بعد العمل مفيدة. كما يسهّل على الآخرين أن يفعلوا الشيء نفسه.'),
];
